import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-121: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short121', durationInSeconds: 32.9, fps: 30, width: 1080, height: 1920 };

const T = [secToFrame(4.3), secToFrame(6.6), secToFrame(12.5), secToFrame(15.9), secToFrame(22.5), secToFrame(27.0)];
const CTA = secToFrame(30.4);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short121: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'OPUS 5.5 $4 IN' }, { text: 'OLD OPUS $5 IN', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={T[0]}>
        <CoverImage src="projects/short-121/cover.png" out={T[0] - 10} />
        <HookTitle hold onDark kicker="CLAUDE PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={T[1]}>
        <ToolCard name="Opus 5.5" tagline="The new one." chip="$4 / $20" at={T[0] - 2}>
          <Panel>
            <Line k="input /1M" v="$4.00" good />
            <Line k="output /1M" v="$20.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[2]}>
        <ToolCard name="Opus 5" tagline="The old one." chip="$5 / $25" at={T[1] - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$5.00" bad />
            <Line k="output /1M" v="$25.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[3]}>
        <ToolCard name="20% cheaper" tagline="Both sides." chip="-20%" at={T[2] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input" v="$5 to $4" good />
            <Line k="output" v="$25 to $20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[4]}>
        <ToolCard name="Cache hits" tagline="Even lower." chip="$0.20" at={T[3] - 2}>
          <Panel>
            <Line k="Opus 5" v="$0.50" bad />
            <Line k="Opus 5.5" v="$0.20" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[5]}>
        <ToolCard name="Sonnet 5.5" tagline="Sits below." chip="$2 / $10" at={T[4] - 2}>
          <Panel>
            <Line k="input /1M" v="$2.00" />
            <Line k="output /1M" v="$10.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Old Opus" tagline="Still pinned?" chip="-20%" at={T[5] - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="old input" v="$5" bad />
            <Line k="new input" v="$4" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-121/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Four dollars beats five.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short121;
